export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: 'quote';
  items: Item[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimStep {
  op: 'claim';
  policy: number;
  incident: { cause: string; damages: Damage[] };
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export type StepResult =
  | { premium: number }
  | { payout: number; remainingCap: number };

export interface ScenarioOutput {
  results: StepResult[];
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;
const CURSE_SURCHARGE = 0.5;
const HIGH_ENCHANTMENT_LEVEL = 5;
const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
const LOYALTY_YEARS = 2;
const LOYALTY_DISCOUNT = 0.2;
const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;

const MAIN_ITEM_BASE_PREMIUM: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

function quotePremium(
  items: Item[],
  customer: Customer,
  previousContracts: number,
): number {
  const policyBase = items.reduce(
    (sum, item) => sum + MAIN_ITEM_BASE_PREMIUM[item.type],
    0,
  );
  const itemSurcharges = items.reduce((sum, item) => {
    const base = MAIN_ITEM_BASE_PREMIUM[item.type];
    const curse = item.cursed ? base * CURSE_SURCHARGE : 0;
    const enchanted =
      (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL
        ? base * HIGH_ENCHANTMENT_SURCHARGE
        : 0;
    return sum + curse + enchanted;
  }, 0);
  const firstInsurance = policyBase * FIRST_INSURANCE_SURCHARGE;
  const loyalty =
    customer.yearsWithMHPCO >= LOYALTY_YEARS
      ? policyBase * LOYALTY_DISCOUNT
      : 0;
  const followUp =
    previousContracts > 0 ? policyBase * FOLLOW_UP_CONTRACT_DISCOUNT : 0;
  return Math.ceil(
    policyBase +
      itemSurcharges +
      firstInsurance -
      loyalty -
      followUp +
      PROCESSING_FEE,
  );
}

export function runScenario(scenario: Scenario): ScenarioOutput {
  const results: StepResult[] = [];
  let contracts = 0;

  for (const step of scenario.steps) {
    const quote = step as QuoteStep;
    results.push({
      premium: quotePremium(quote.items, scenario.customer, contracts),
    });
    contracts += 1;
  }

  return { results };
}

